#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/xmlmemory.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static long fail_at = -1;
static long alloc_count = 0;

static void *my_malloc(size_t n) {
    if (fail_at >= 0 && alloc_count >= fail_at) {
        alloc_count++;
        return NULL;
    }
    alloc_count++;
    return malloc(n);
}
static void my_free(void *p) { free(p); }
static void *my_realloc(void *p, size_t n) { return realloc(p, n); }
static char *my_strdup(const char *s) { return strdup(s); }

static int count_dtd_children(const xmlDocPtr doc) {
    int c = 0;
    xmlNodePtr n;
    for (n = doc->children; n != NULL; n = n->next)
        if (n->type == XML_DTD_NODE)
            c++;
