int main(int argc, char **argv) {
    long max_fail = (argc > 1) ? atol(argv[1]) : 40;
    long f;
    int first_copy_seen = 0;

    if (xmlMemSetup(my_free, my_malloc, my_realloc, my_strdup) != 0) {
        fprintf(stderr, "xmlMemSetup failed\n");
        return 2;
    }
    xmlInitParser();

    const char *src =
