            xmlFreeDoc(cp);
            (void) sink;
        }
    }

    printf("swept fail_at 0..%ld; first_copy_seen=%d\n", max_fail, first_copy_seen);
    printf("REGRESSION-PASS\n");
    xmlFreeDoc(doc);
    xmlCleanupParser();
    return 0;
}

