/*
 * Focused regression for upstream libxml2 commit d39f7806
 * "tree: Fix copying of DTDs" (issue #583), ported onto the 2.9.12 target
 * plus downstream patches.
 *
 * It tests the two machine-checkable security invariants introduced by the
 * fix, using only public API:
 *
 *   INV-1 (no aliasing/duplication): xmlDocCopyNodeList(dest, src->children)
 *        must not return the destination document's own internal subset as a
 *        copied DTD node when dest->intSubset is already set.  The vulnerable
 *        code enters the old `else` branch and links dest->intSubset into the
 *        returned node list, aliasing the document's DTD into a detached list
 *        that callers may attach/free.
 *
 *   INV-2 (no intSubset on failed copy): if the list copy fails part-way
 *        (injected allocation failure), dest->intSubset must remain NULL.
 *        The vulnerable code assigns doc->intSubset = q inside the loop, so a
 *        later failure leaves the document pointing at a node freed/owned by
 *        the aborted copy.  The fix defers the assignment until completion.
 *
 * Exit 0 and print REGRESSION-PASS only when both invariants hold.
 */
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/xmlmemory.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static long fail_at = -1;
static long alloc_count = 0;

static void *my_malloc(size_t n) {
    if (fail_at >= 0 && alloc_count >= fail_at) {
        alloc_count++;
        return NULL;
    }
    alloc_count++;
    return malloc(n);
}
static void my_free(void *p) { free(p); }
static void *my_realloc(void *p, size_t n) { return realloc(p, n); }
static char *my_strdup(const char *s) { return strdup(s); }

static const char *SRC =
    "<!DOCTYPE root [<!ELEMENT root (#PCDATA)><!ENTITY e \"x\">]>"
    "<root>&e;</root>";

int main(void) {
    xmlDocPtr src;
    int inv1_violations = 0;
    int inv2_violations = 0;
    int failed_copies = 0;
    long f;

    if (xmlMemSetup(my_free, my_malloc, my_realloc, my_strdup) != 0) {
        fprintf(stderr, "xmlMemSetup failed\n");
        return 2;
    }
    xmlInitParser();

    src = xmlReadMemory(SRC, (int) strlen(SRC), "t.xml", NULL, 0);
    if (src == NULL) {
        fprintf(stderr, "source parse failed\n");
        return 2;
    }
    if (src->intSubset == NULL) {
        fprintf(stderr, "source has no intSubset\n");
        return 2;
    }

    /* ---- INV-1: destination already owns an internal subset ---- */
    {
        xmlDocPtr dest = xmlNewDoc((const xmlChar *) "1.0");
        xmlNodePtr list;

        dest->intSubset = xmlCopyDtd(src->intSubset);
        if (dest->intSubset == NULL) {
            fprintf(stderr, "could not seed dest intSubset\n");
            return 2;
        }
        xmlSetTreeDoc((xmlNodePtr) dest->intSubset, dest);
        dest->intSubset->parent = dest;

        list = xmlDocCopyNodeList(dest, src->children);
        if (list != NULL) {
            xmlNodePtr n;
            for (n = list; n != NULL; n = n->next) {
                if (n == (xmlNodePtr) dest->intSubset) {
                    inv1_violations++;
                    printf("INV-1 VIOLATION: copied list aliases dest->intSubset %p (node type %d)\n",
                           (void *) dest->intSubset, n->type);
                    break;
                }
            }
            xmlFreeNodeList(list);
        }
        xmlFreeDoc(dest);
    }

    /* ---- INV-2: failed copy must not publish dest->intSubset ---- */
    for (f = 0; f <= 300; f++) {
        xmlDocPtr dest = xmlNewDoc((const xmlChar *) "1.0");
        xmlNodePtr list;

        fail_at = f;
        alloc_count = 0;
        list = xmlDocCopyNodeList(dest, src->children);
        fail_at = -1;

        if (list == NULL) {
            failed_copies++;
            if (dest->intSubset != NULL) {
                inv2_violations++;
                if (inv2_violations <= 3)
                    printf("INV-2 VIOLATION at fail_at=%ld: failed copy left dest->intSubset=%p\n",
                           f, (void *) dest->intSubset);
            }
        } else {
            xmlFreeNodeList(list);
        }
        xmlFreeDoc(dest);
    }

    printf("source intSubset=%p; failed_copies_examined=%d\n",
           (void *) src->intSubset, failed_copies);
    printf("INV-1 violations=%d INV-2 violations=%d\n",
           inv1_violations, inv2_violations);

    xmlFreeDoc(src);
    xmlCleanupParser();

    if (inv1_violations == 0 && inv2_violations == 0 && failed_copies > 0) {
        printf("REGRESSION-PASS\n");
        return 0;
    }
    printf("REGRESSION-FAIL\n");
    return 1;
}

/*
 * Focused regression for upstream libxml2 commit d39f7806
 * "tree: Fix copying of DTDs" (issue #583), ported onto the 2.9.12 target
 * plus downstream patches.
 *
 * Deterministic, non-crashing checks of the two security invariants that the
 * fix establishes in xmlStaticCopyNodeList(), exercised through the public
 * xmlDocCopyNodeList() API:
 *
 *   INV-1 (no aliasing/duplication): when the destination document already
 *        owns an internal subset, the node list returned by
 *        xmlDocCopyNodeList(dest, src->children) must not contain
 *        dest->intSubset.  The vulnerable code re-enters the old `else` branch
 *        and links dest->intSubset into the returned list, so the document's
 *        DTD and the detached list alias the same node.
 *
 *   INV-2 (no intSubset on failed copy): if the list copy fails part-way
 *        (injected allocation failure), dest->intSubset must remain NULL.
 *        The vulnerable code assigns doc->intSubset = q inside the loop, so a
 *        later failure publishes a node owned by the aborted copy.
 *
 * Cleanup always detaches dest->intSubset first, so this program reports the
 * invariant violations instead of aborting; the companion
 * regression_dtd_uaf.c deliberately keeps the aliased list ownership and lets
 * ASan catch the resulting use-after-free on the vulnerable build.
 *
 * Exit 0 and print REGRESSION-PASS only when both invariants hold.
 */
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <libxml/xmlmemory.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static long fail_at = -1;
static long alloc_count = 0;

static void *my_malloc(size_t n) {
    if (fail_at >= 0 && alloc_count >= fail_at) {
        alloc_count++;
        return NULL;
    }
    alloc_count++;
    return malloc(n);
}
static void my_free(void *p) { free(p); }
static void *my_realloc(void *p, size_t n) { return realloc(p, n); }
static char *my_strdup(const char *s) { return strdup(s); }

static const char *SRC =
    "<!DOCTYPE root [<!ELEMENT root (#PCDATA)><!ENTITY e \"x\">]>"
    "<root>&e;</root>";

int main(void) {
    xmlDocPtr src;
    int inv1_violations = 0;
    int inv2_violations = 0;
    int failed_copies = 0;
    long f;

    if (xmlMemSetup(my_free, my_malloc, my_realloc, my_strdup) != 0) {
        fprintf(stderr, "xmlMemSetup failed\n");
        return 2;
    }
    xmlInitParser();

    src = xmlReadMemory(SRC, (int) strlen(SRC), "t.xml", NULL, 0);
    if (src == NULL || src->intSubset == NULL) {
        fprintf(stderr, "source parse failed or has no intSubset\n");
        return 2;
    }

    /* ---- INV-1: destination already owns an internal subset ---- */
    {
        xmlDocPtr dest = xmlNewDoc((const xmlChar *) "1.0");
        xmlNodePtr list;

        dest->intSubset = xmlCopyDtd(src->intSubset);
        if (dest->intSubset == NULL) {
            fprintf(stderr, "could not seed dest intSubset\n");
            return 2;
        }
        xmlSetTreeDoc((xmlNodePtr) dest->intSubset, dest);
        dest->intSubset->parent = dest;

        list = xmlDocCopyNodeList(dest, src->children);
        if (list != NULL) {
            xmlNodePtr n;
            for (n = list; n != NULL; n = n->next) {
                if (n == (xmlNodePtr) dest->intSubset) {
                    inv1_violations++;
                    printf("INV-1 VIOLATION: copied list aliases dest->intSubset %p (type %d)\n",
                           (void *) dest->intSubset, n->type);
                    break;
                }
            }
            /* Single-owner cleanup: detach the destination subset, then free
             * the detached list.  Leaks are irrelevant (detect_leaks=0). */
            dest->intSubset = NULL;
            xmlFreeNodeList(list);
        } else {
            inv1_violations++;
            printf("INV-1 VIOLATION: copy unexpectedly returned NULL\n");
        }
        xmlFreeDoc(dest);
    }

    /* ---- INV-2: failed copy must not publish dest->intSubset ---- */
    for (f = 0; f <= 300; f++) {
        xmlDocPtr dest = xmlNewDoc((const xmlChar *) "1.0");
        xmlNodePtr list;

        fail_at = f;
        alloc_count = 0;
        list = xmlDocCopyNodeList(dest, src->children);
        fail_at = -1;

        if (list == NULL) {
            failed_copies++;
            if (dest->intSubset != NULL) {
                inv2_violations++;
                if (inv2_violations <= 3)
                    printf("INV-2 VIOLATION at fail_at=%ld: failed copy published dest->intSubset=%p\n",
                           f, (void *) dest->intSubset);
            }
        } else {
            xmlFreeNodeList(list);
        }
        dest->intSubset = NULL;   /* keep ownership single for cleanup */
        xmlFreeDoc(dest);
    }

    printf("source intSubset=%p; failed_copies_examined=%d\n",
           (void *) src->intSubset, failed_copies);
    printf("INV-1 violations=%d INV-2 violations=%d\n",
           inv1_violations, inv2_violations);

    xmlFreeDoc(src);
    xmlCleanupParser();

    if (inv1_violations == 0 && inv2_violations == 0 && failed_copies > 0) {
        printf("REGRESSION-PASS\n");
        return 0;
    }
    printf("REGRESSION-FAIL\n");
    return 1;
}

/*
 * Use-after-free demonstrator for upstream libxml2 commit d39f7806
 * "tree: Fix copying of DTDs" (issue #583).
 *
 * Public API usage only:
 *   1. a destination document that already owns an internal subset,
 *   2. xmlDocCopyNodeList(dest, src->children) to obtain a copied node list,
 *   3. the caller frees that returned list (it is documented as a list of
 *      copies), and then frees the destination document.
 *
 * On the vulnerable implementation the old `else` branch links
 * dest->intSubset itself into the returned list.  Freeing the list leaves
 * dest->intSubset->next dangling at the freed element node, so the later
 * xmlFreeDoc() -> xmlUnlinkNode(intSubset) dereferences freed memory.  ASan
 * reports heap-use-after-free.
 *
 * On the fixed implementation the destination subset is skipped during the
 * copy, so the same sequence is safe and the program prints UAF-DEMO-SAFE.
 */
#include <libxml/parser.h>
#include <libxml/tree.h>

#include <stdio.h>
#include <string.h>

static const char *SRC =
    "<!DOCTYPE root [<!ELEMENT root (#PCDATA)><!ENTITY e \"x\">]>"
    "<root>&e;</root>";

int main(void) {
    xmlDocPtr src;
    xmlDocPtr dest;
    xmlNodePtr list;

    src = xmlReadMemory(SRC, (int) strlen(SRC), "t.xml", NULL, 0);
    if (src == NULL || src->intSubset == NULL) {
        fprintf(stderr, "source parse failed\n");
        return 2;
    }

    dest = xmlNewDoc((const xmlChar *) "1.0");
    dest->intSubset = xmlCopyDtd(src->intSubset);
    if (dest->intSubset == NULL) {
        fprintf(stderr, "could not seed dest intSubset\n");
        return 2;
    }
    xmlSetTreeDoc((xmlNodePtr) dest->intSubset, dest);
    dest->intSubset->parent = dest;

    list = xmlDocCopyNodeList(dest, src->children);
    if (list != NULL)
        xmlFreeNodeList(list);      /* caller owns and frees the returned list */

    xmlFreeDoc(dest);               /* vulnerable: intSubset->next is dangling */
    xmlFreeDoc(src);

    printf("UAF-DEMO-SAFE\n");
    return 0;
}

